/**
 * pyvalues.mjs — Python runtime value model for Node.js.
 *
 * Mapping between Python values and their JS representation:
 *
 *   Python        JS
 *   ------        --------------------------------
 *   None          null
 *   bool          boolean
 *   int           BigInt          (arbitrary precision, like Python)
 *   float         number          (IEEE-754 double)
 *   str           string
 *   bytes         PyBytes
 *   list          Array
 *   tuple         PyTuple
 *   set           PySet
 *   dict          PyDict
 *   range         PyRange
 *
 * Keeping `int` as BigInt and `float` as number is what makes
 * `type(x).__name__`, `isinstance(x, int)` and exact integer arithmetic
 * behave the same way they do in CPython.
 */

/** Marker used to let containers expose their own repr implementation. */
export const PY_REPR = Symbol('__repr__');

/* ------------------------------------------------------------------ *
 * Containers
 * ------------------------------------------------------------------ */

export class PyTuple {
  constructor(items = []) {
    this.items = Array.from(items);
  }

  get length() {
    return this.items.length;
  }

  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }
}

export class PyBytes {
  /** @param {number[]|Uint8Array} bytes */
  constructor(bytes = []) {
    this.bytes = Uint8Array.from(bytes);
  }

  get length() {
    return this.bytes.length;
  }
}

export class PyRange {
  constructor(start, stop, step) {
    this.start = start;
    this.stop = stop;
    this.step = step;
  }

  toArray() {
    const out = [];
    const { start, stop, step } = this;
    if (step > 0n) {
      for (let i = start; i < stop; i += step) out.push(i);
    } else if (step < 0n) {
      for (let i = start; i > stop; i += step) out.push(i);
    }
    return out;
  }

  [Symbol.iterator]() {
    return this.toArray()[Symbol.iterator]();
  }
}

/* ------------------------------------------------------------------ *
 * Hashing / key identity
 * ------------------------------------------------------------------ */

let nanCounter = 0;

/**
 * Canonical string for dict/set key identity.
 *
 * Mirrors CPython's equality rules for keys: `True == 1 == 1.0`, so all
 * three collapse onto the same slot, and the *first* inserted key object
 * is the one that is kept.
 */
export function canonicalKey(value) {
  if (value === null) return 'None';
  const t = typeof value;
  if (t === 'boolean') return `#${value ? '1' : '0'}`;
  if (t === 'bigint') return `#${value}`;
  if (t === 'number') {
    if (Number.isNaN(value)) return `#nan${nanCounter++}`; // nan != nan
    if (!Number.isFinite(value)) return `#${value > 0 ? 'inf' : '-inf'}`;
    if (Number.isInteger(value) && Math.abs(value) < 1e21) {
      return `#${BigInt(value)}`;
    }
    return `#${value}`;
  }
  if (t === 'string') return `s${value}`;
  if (value instanceof PyBytes) return `b${Array.from(value.bytes).join(',')}`;
  if (value instanceof PyTuple) {
    return `t(${value.items.map(canonicalKey).join(',')})`;
  }
  throw new PyError('TypeError', `unhashable type: '${typeName(value)}'`);
}

/** Python-style exception carrier (name + message). */
export class PyError extends Error {
  constructor(name, message) {
    super(message);
    this.pyName = name;
    this.pyMessage = message;
  }
}

/* ------------------------------------------------------------------ *
 * dict
 * ------------------------------------------------------------------ */

export class PyDict {
  constructor(entries = []) {
    /** @type {Map<string, {key: any, value: any}>} */
    this._map = new Map();
    for (const [k, v] of entries) this.set(k, v);
  }

  get size() {
    return this._map.size;
  }

  set(key, value) {
    const ck = canonicalKey(key);
    const slot = this._map.get(ck);
    if (slot === undefined) {
      this._map.set(ck, { key, value });
    } else {
      slot.value = value; // key object of the first insertion is preserved
    }
    return this;
  }

  has(key) {
    return this._map.has(canonicalKey(key));
  }

  get(key, fallback = undefined) {
    const slot = this._map.get(canonicalKey(key));
    return slot === undefined ? fallback : slot.value;
  }

  keys() {
    return Array.from(this._map.values(), (slot) => slot.key);
  }

  values() {
    return Array.from(this._map.values(), (slot) => slot.value);
  }

  items() {
    return Array.from(this._map.values(), (slot) => new PyTuple([slot.key, slot.value]));
  }

  /** Plain [key, value] pairs — convenient for JS-side iteration. */
  entries() {
    return Array.from(this._map.values(), (slot) => [slot.key, slot.value]);
  }

  /** Iterating a dict yields its keys, as in Python. */
  [Symbol.iterator]() {
    return this.keys()[Symbol.iterator]();
  }
}

/* ------------------------------------------------------------------ *
 * set
 * ------------------------------------------------------------------ */

export class PySet {
  constructor(items = []) {
    this._map = new Map();
    for (const item of items) this.add(item);
  }

  get size() {
    return this._map.size;
  }

  add(item) {
    const ck = canonicalKey(item);
    if (!this._map.has(ck)) this._map.set(ck, item);
    return this;
  }

  values() {
    return Array.from(this._map.values());
  }

  [Symbol.iterator]() {
    return this.values()[Symbol.iterator]();
  }
}

/* ------------------------------------------------------------------ *
 * Type inspection
 * ------------------------------------------------------------------ */

/** Equivalent of `type(value).__name__`. */
export function typeName(value) {
  if (value === null) return 'NoneType';
  switch (typeof value) {
    case 'boolean':
      return 'bool';
    case 'bigint':
      return 'int';
    case 'number':
      return 'float';
    case 'string':
      return 'str';
    default:
      break;
  }
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PySet) return 'set';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PyBytes) return 'bytes';
  if (value instanceof PyRange) return 'range';
  if (value && typeof value.__pyclass__ === 'string') return value.__pyclass__;
  return 'object';
}

/** `isinstance(value, int)` — note that in Python `bool` is a subclass of `int`. */
export function isPyInt(value) {
  return typeof value === 'bigint' || typeof value === 'boolean';
}

/** `isinstance(value, float)`. */
export function isPyFloat(value) {
  return typeof value === 'number';
}

/** `isinstance(value, (int, float))`. */
export function isPyNumber(value) {
  return isPyInt(value) || isPyFloat(value);
}

/** Numeric value of an int-ish object (bool -> 1/0) as BigInt. */
export function asBigInt(value) {
  if (typeof value === 'bigint') return value;
  if (typeof value === 'boolean') return value ? 1n : 0n;
  throw new PyError('TypeError', `not an integer: ${typeName(value)}`);
}

/* ------------------------------------------------------------------ *
 * Operators with Python semantics
 * ------------------------------------------------------------------ */

/** Python `%` — result carries the sign of the divisor (floored modulo). */
export function pyMod(a, b) {
  if (isPyInt(a) && isPyInt(b)) {
    const x = asBigInt(a);
    const y = asBigInt(b);
    if (y === 0n) throw new PyError('ZeroDivisionError', 'integer modulo by zero');
    let r = x % y;
    if (r !== 0n && (r < 0n) !== (y < 0n)) r += y;
    return r;
  }
  const x = toJsNumber(a);
  const y = toJsNumber(b);
  if (y === 0) throw new PyError('ZeroDivisionError', 'float modulo');
  const r = x - Math.floor(x / y) * y;
  return r;
}

/** Numeric coercion to a JS double (used for float arithmetic/comparison). */
export function toJsNumber(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'bigint') return Number(value);
  if (typeof value === 'boolean') return value ? 1 : 0;
  throw new PyError('TypeError', `unsupported operand type: ${typeName(value)}`);
}

/** Python `>` restricted to the numeric types this program can produce. */
export function pyGreaterThan(a, b) {
  if (isPyInt(a) && isPyInt(b)) return asBigInt(a) > asBigInt(b);
  if (typeof a === 'bigint' && typeof b === 'number') return Number.isNaN(b) ? false : a > b;
  if (typeof a === 'number' && typeof b === 'bigint') return Number.isNaN(a) ? false : a > b;
  return toJsNumber(a) > toJsNumber(b);
}

/** Python `len()`; strings are measured in code points, not UTF-16 units. */
export function pyLen(value) {
  if (typeof value === 'string') return BigInt(codePointLength(value));
  if (Array.isArray(value)) return BigInt(value.length);
  if (value instanceof PyTuple) return BigInt(value.items.length);
  if (value instanceof PyBytes) return BigInt(value.bytes.length);
  if (value instanceof PySet) return BigInt(value.size);
  if (value instanceof PyDict) return BigInt(value.size);
  if (value instanceof PyRange) return BigInt(value.toArray().length);
  if (value && typeof value.pyLength === 'function') return BigInt(value.pyLength());
  throw new PyError('TypeError', `object of type '${typeName(value)}' has no len()`);
}

export function codePointLength(str) {
  let n = 0;
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i++; // surrogate pair -> one code point
    }
    n++;
  }
  return n;
}

