/**
 * pyformat.mjs — CPython-compatible `repr()`, `str()` and `print()`.
 */

import {
  PyBytes,
  PyDict,
  PyRange,
  PySet,
  PyTuple,
  PY_REPR,
  typeName,
} from './pyvalues.mjs';

/* ------------------------------------------------------------------ *
 * float
 * ------------------------------------------------------------------ */

/**
 * `repr(float)`.
 *
 * CPython prints the shortest string that round-trips, and switches to
 * exponential notation when the decimal point position `decpt` satisfies
 * `decpt <= -4 || decpt > 16`. The exponent always carries a sign and at
 * least two digits, and fixed notation always keeps a fractional part.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (value === 0) return Object.is(value, -0) ? '-0.0' : '0.0';

  const negative = value < 0;
  const abs = Math.abs(value);

  // toExponential() without an argument yields the shortest round-tripping
  // digit string, e.g. 0.30000000000000004 -> "3.0000000000000004e-1".
  const exponential = abs.toExponential();
  const [mantissa, exponentText] = exponential.split('e');
  const digits = mantissa.replace('.', '').replace(/0+$/, '') || '0';
  const decpt = Number(exponentText) + 1;

  let body;
  if (decpt <= -4 || decpt > 16) {
    const exponent = decpt - 1;
    const tail = digits.length > 1 ? `.${digits.slice(1)}` : '';
    const sign = exponent < 0 ? '-' : '+';
    const magnitude = String(Math.abs(exponent)).padStart(2, '0');
    body = `${digits[0]}${tail}e${sign}${magnitude}`;
  } else if (decpt <= 0) {
    body = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    body = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }
  return negative ? `-${body}` : body;
}

/* ------------------------------------------------------------------ *
 * str
 * ------------------------------------------------------------------ */

// Python's str.isprintable() is false for the Unicode categories below
// (ASCII space being the one separator that stays printable).
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(codePoint) {
  const char = String.fromCodePoint(codePoint);
  if (char === ' ') return true;
  return !NON_PRINTABLE.test(char);
}

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/** `repr(str)` — prefers single quotes, switching to double quotes as Python does. */
export function strRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = quote;
  for (const char of value) {
    const codePoint = char.codePointAt(0);
    if (char === quote || char === '\\') {
      out += `\\${char}`;
    } else if (char === '\n') {
      out += '\\n';
    } else if (char === '\r') {
      out += '\\r';
    } else if (char === '\t') {
      out += '\\t';
    } else if (!isPrintable(codePoint)) {
      out += escapeCodePoint(codePoint);
    } else {
      out += char;
    }
  }
  return out + quote;
}

/** `repr(bytes)`. */
export function bytesRepr(value) {
  const chars = Array.from(value.bytes, (byte) => String.fromCharCode(byte));
  const text = chars.join('');
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = `b${quote}`;
  for (const byte of value.bytes) {
    const char = String.fromCharCode(byte);
    if (char === quote || char === '\\') out += `\\${char}`;
    else if (char === '\n') out += '\\n';
    else if (char === '\r') out += '\\r';
    else if (char === '\t') out += '\\t';
    else if (byte >= 0x20 && byte < 0x7f) out += char;
    else out += `\\x${byte.toString(16).padStart(2, '0')}`;
  }
  return out + quote;
}

/* ------------------------------------------------------------------ *
 * repr / str
 * ------------------------------------------------------------------ */

/** `repr(value)`. */
export function pyRepr(value) {
  if (value === null) return 'None';
  switch (typeof value) {
    case 'boolean':
      return value ? 'True' : 'False';
    case 'bigint':
      return String(value);
    case 'number':
      return floatRepr(value);
    case 'string':
      return strRepr(value);
    default:
      break;
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  if (value instanceof PyTuple) {
    const inner = value.items.map(pyRepr).join(', ');
    return value.items.length === 1 ? `(${inner},)` : `(${inner})`;
  }
  if (value instanceof PySet) {
    const items = value.values();
    return items.length === 0 ? 'set()' : `{${items.map(pyRepr).join(', ')}}`;
  }
  if (value instanceof PyDict) {
    const body = value
      .entries()
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  if (value instanceof PyBytes) return bytesRepr(value);
  if (value instanceof PyRange) {
    return `range(${value.start}, ${value.stop}${value.step === 1n ? '' : `, ${value.step}`})`;
  }
  if (value && typeof value[PY_REPR] === 'function') return value[PY_REPR]();
  return `<${typeName(value)} object>`;
}

/** `str(value)` — identical to repr() except that strings pass through. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

/** `print(value)`. */
export function pyPrint(value) {
  process.stdout.write(`${pyStr(value)}\n`);
}

