/**
 * pyeval.mjs — evaluator for the subset of Python expressions that `eval()`
 * receives here: nested literal structures plus the occasional arithmetic
 * expression or builtin call (`float('inf')`, `range(3)`, ...).
 *
 * Implemented as a tokenizer plus a recursive-descent parser so that
 * precedence and int/float distinctions match CPython.
 */

import {
  PyBytes,
  PyDict,
  PyError,
  PyRange,
  PySet,
  PyTuple,
  asBigInt,
  codePointLength,
  isPyInt,
  pyLen,
  pyMod,
  toJsNumber,
  typeName,
} from './pyvalues.mjs';
import { pyStr } from './pyformat.mjs';

const SYNTAX_ERROR = () => new PyError('SyntaxError', 'invalid syntax');

/* ------------------------------------------------------------------ *
 * Tokenizer
 * ------------------------------------------------------------------ */

const PUNCTUATION = ['**', '//', '{', '}', '[', ']', '(', ')', ',', ':', '+', '-', '*', '/', '%'];
const STRING_PREFIXES = ['rb', 'br', 'r', 'b', 'u', 'f'];

function tokenize(source) {
  const tokens = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ' || char === '\t' || char === '\n' || char === '\r' || char === '\\') {
      i++;
      continue;
    }
    if (char === '#') {
      while (i < source.length && source[i] !== '\n') i++;
      continue;
    }

    // String literal, with optional prefix.
    const prefixMatch = /^([A-Za-z]{1,2})?['"]/.exec(source.slice(i, i + 3));
    if (prefixMatch && (!prefixMatch[1] || STRING_PREFIXES.includes(prefixMatch[1].toLowerCase()))) {
      const prefix = (prefixMatch[1] || '').toLowerCase();
      const [value, next] = readString(source, i + prefix.length, prefix);
      tokens.push({ type: 'string', value, prefix });
      i = next;
      continue;
    }

    if (/[0-9]/.test(char) || (char === '.' && /[0-9]/.test(source[i + 1] || ''))) {
      const [value, next] = readNumber(source, i);
      tokens.push({ type: 'number', value });
      i = next;
      continue;
    }

    if (/[A-Za-z_]/.test(char)) {
      let j = i;
      while (j < source.length && /[A-Za-z0-9_]/.test(source[j])) j++;
      tokens.push({ type: 'name', value: source.slice(i, j) });
      i = j;
      continue;
    }

    const punctuation = PUNCTUATION.find((op) => source.startsWith(op, i));
    if (punctuation) {
      tokens.push({ type: 'op', value: punctuation });
      i += punctuation.length;
      continue;
    }

    throw SYNTAX_ERROR();
  }

  tokens.push({ type: 'eof', value: null });
  return tokens;
}

const SIMPLE_ESCAPES = {
  n: '\n',
  t: '\t',
  r: '\r',
  '\\': '\\',
  "'": "'",
  '"': '"',
  a: '\x07',
  b: '\b',
  f: '\f',
  v: '\v',
  0: '\0',
};

function readString(source, start, prefix) {
  const raw = prefix.includes('r');
  const quoteChar = source[start];
  const triple = source.startsWith(quoteChar.repeat(3), start);
  const delimiter = triple ? quoteChar.repeat(3) : quoteChar;
  let i = start + delimiter.length;
  let out = '';

  while (i < source.length) {
    if (source.startsWith(delimiter, i)) {
      return [out, i + delimiter.length];
    }
    const char = source[i];
    if (char === '\\' && !raw) {
      const escape = source[i + 1];
      if (escape === undefined) throw SYNTAX_ERROR();
      if (escape === '\n') {
        i += 2;
        continue;
      }
      if (escape === 'x' || escape === 'u' || escape === 'U') {
        const width = escape === 'x' ? 2 : escape === 'u' ? 4 : 8;
        const hex = source.slice(i + 2, i + 2 + width);
        if (!new RegExp(`^[0-9a-fA-F]{${width}}$`).test(hex)) throw SYNTAX_ERROR();
        out += String.fromCodePoint(parseInt(hex, 16));
        i += 2 + width;
        continue;
      }
      if (Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, escape)) {
        out += SIMPLE_ESCAPES[escape];
        i += 2;
        continue;
      }
      out += `\\${escape}`; // unknown escapes stay literal, as in Python
      i += 2;
      continue;
    }
    if (char === '\\' && raw) {
      out += source.slice(i, i + 2);
      i += 2;
      continue;
    }
    out += char;
    i++;
  }
  throw SYNTAX_ERROR();
}

function readNumber(source, start) {
  const radixMatch = /^0[xXoObB][0-9a-fA-F_]+/.exec(source.slice(start));
  if (radixMatch) {
    const text = radixMatch[0].replace(/_/g, '');
    return [BigInt(text), start + radixMatch[0].length];
  }
  const match = /^[0-9_]*(\.[0-9_]*)?([eE][+-]?[0-9_]+)?/.exec(source.slice(start));
  if (!match || match[0] === '') throw SYNTAX_ERROR();
  const text = match[0].replace(/_/g, '');
  const isFloat = text.includes('.') || /[eE]/.test(text);
  const value = isFloat ? Number(text) : BigInt(text);
  if (typeof value === 'number' && Number.isNaN(value)) throw SYNTAX_ERROR();
  return [value, start + match[0].length];
}

/* ------------------------------------------------------------------ *
 * Arithmetic with Python semantics
 * ------------------------------------------------------------------ */

function pyAdd(a, b) {
  if (isPyInt(a) && isPyInt(b)) return asBigInt(a) + asBigInt(b);
  if (typeof a === 'string' && typeof b === 'string') return a + b;
  if (Array.isArray(a) && Array.isArray(b)) return [...a, ...b];
  if (a instanceof PyTuple && b instanceof PyTuple) return new PyTuple([...a.items, ...b.items]);
  return toJsNumber(a) + toJsNumber(b);
}

function pySub(a, b) {
  if (isPyInt(a) && isPyInt(b)) return asBigInt(a) - asBigInt(b);
  return toJsNumber(a) - toJsNumber(b);
}

function pyMul(a, b) {
  if (isPyInt(a) && isPyInt(b)) return asBigInt(a) * asBigInt(b);
  if (typeof a === 'string' && isPyInt(b)) return a.repeat(Math.max(0, Number(asBigInt(b))));
  if (isPyInt(a) && typeof b === 'string') return b.repeat(Math.max(0, Number(asBigInt(a))));
  if (Array.isArray(a) && isPyInt(b)) return repeatList(a, Number(asBigInt(b)));
  if (isPyInt(a) && Array.isArray(b)) return repeatList(b, Number(asBigInt(a)));
  return toJsNumber(a) * toJsNumber(b);
}

function repeatList(list, times) {
  const out = [];
  for (let i = 0; i < times; i++) out.push(...list);
  return out;
}

function pyTrueDiv(a, b) {
  const y = toJsNumber(b);
  if (y === 0) throw new PyError('ZeroDivisionError', 'division by zero');
  return toJsNumber(a) / y;
}

function pyFloorDiv(a, b) {
  if (isPyInt(a) && isPyInt(b)) {
    const x = asBigInt(a);
    const y = asBigInt(b);
    if (y === 0n) throw new PyError('ZeroDivisionError', 'integer division or modulo by zero');
    let q = x / y;
    if ((x % y !== 0n) && ((x < 0n) !== (y < 0n))) q -= 1n;
    return q;
  }
  const y = toJsNumber(b);
  if (y === 0) throw new PyError('ZeroDivisionError', 'float floor division by zero');
  return Math.floor(toJsNumber(a) / y);
}

function pyPow(a, b) {
  if (isPyInt(a) && isPyInt(b) && asBigInt(b) >= 0n) return asBigInt(a) ** asBigInt(b);
  return toJsNumber(a) ** toJsNumber(b);
}

function pyNegate(value) {
  if (isPyInt(value)) return -asBigInt(value);
  return -toJsNumber(value);
}

export function pyTruthy(value) {
  if (value === null || value === false) return false;
  if (value === true) return true;
  if (typeof value === 'bigint') return value !== 0n;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') return value.length > 0;
  return Number(pyLen(value)) > 0;
}

/* ------------------------------------------------------------------ *
 * Builtins reachable from eval()
 * ------------------------------------------------------------------ */

function iterate(value) {
  if (typeof value === 'string') return Array.from(value);
  if (Array.isArray(value)) return value.slice();
  if (value instanceof PyTuple) return value.items.slice();
  if (value instanceof PySet) return value.values();
  if (value instanceof PyDict) return value.keys();
  if (value instanceof PyRange) return value.toArray();
  if (value instanceof PyBytes) return Array.from(value.bytes, (byte) => BigInt(byte));
  throw new PyError('TypeError', `'${typeName(value)}' object is not iterable`);
}

const BUILTINS = {
  float(args) {
    if (args.length === 0) return 0;
    const value = args[0];
    if (typeof value === 'string') {
      const text = value.trim().toLowerCase();
      if (text === 'inf' || text === '+inf' || text === 'infinity') return Infinity;
      if (text === '-inf' || text === '-infinity') return -Infinity;
      if (text === 'nan' || text === '+nan' || text === '-nan') return NaN;
      const parsed = Number(text);
      if (Number.isNaN(parsed)) {
        throw new PyError('ValueError', `could not convert string to float: ${pyStr(value)}`);
      }
      return parsed;
    }
    return toJsNumber(value);
  },
  int(args) {
    if (args.length === 0) return 0n;
    const value = args[0];
    if (typeof value === 'string') {
      const text = value.trim().replace(/_/g, '');
      if (!/^[+-]?[0-9]+$/.test(text)) {
        throw new PyError('ValueError', `invalid literal for int() with base 10: ${pyStr(value)}`);
      }
      return BigInt(text);
    }
    if (isPyInt(value)) return asBigInt(value);
    return BigInt(Math.trunc(toJsNumber(value)));
  },
  str(args) {
    return args.length === 0 ? '' : pyStr(args[0]);
  },
  bool(args) {
    return args.length === 0 ? false : pyTruthy(args[0]);
  },
  len(args) {
    return pyLen(args[0]);
  },
  abs(args) {
    const value = args[0];
    if (isPyInt(value)) {
      const n = asBigInt(value);
      return n < 0n ? -n : n;
    }
    return Math.abs(toJsNumber(value));
  },
  range(args) {
    if (args.length === 0) throw new PyError('TypeError', 'range expected at least 1 argument, got 0');
    const nums = args.map(asBigInt);
    if (nums.length === 1) return new PyRange(0n, nums[0], 1n);
    return new PyRange(nums[0], nums[1], nums.length > 2 ? nums[2] : 1n);
  },
  list(args) {
    return args.length === 0 ? [] : iterate(args[0]);
  },
  tuple(args) {
    return new PyTuple(args.length === 0 ? [] : iterate(args[0]));
  },
  set(args) {
    return new PySet(args.length === 0 ? [] : iterate(args[0]));
  },
  dict(args) {
    if (args.length === 0) return new PyDict();
    const value = args[0];
    if (value instanceof PyDict) return new PyDict(value.entries());
    if (value && typeof value.toPyDict === 'function') return value.toPyDict();
    const entries = iterate(value).map((pair) => {
      const items = iterate(pair);
      if (items.length !== 2) throw new PyError('ValueError', 'dictionary update sequence error');
      return items;
    });
    return new PyDict(entries);
  },
  sorted(args) {
    const items = iterate(args[0]);
    return items.sort((a, b) => {
      const x = toJsNumber(a);
      const y = toJsNumber(b);
      return x < y ? -1 : x > y ? 1 : 0;
    });
  },
};

/* ------------------------------------------------------------------ *
 * Parser
 * ------------------------------------------------------------------ */

class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  peek(offset = 0) {
    return this.tokens[Math.min(this.pos + offset, this.tokens.length - 1)];
  }

  next() {
    return this.tokens[this.pos++];
  }

  atOp(value) {
    const token = this.peek();
    return token.type === 'op' && token.value === value;
  }

  eatOp(value) {
    if (!this.atOp(value)) throw SYNTAX_ERROR();
    this.pos++;
  }

  /** expression := term (('+' | '-') term)* */
  parseExpression() {
    let left = this.parseTerm();
    while (this.atOp('+') || this.atOp('-')) {
      const op = this.next().value;
      const right = this.parseTerm();
      left = op === '+' ? pyAdd(left, right) : pySub(left, right);
    }
    return left;
  }

  /** term := unary (('*' | '/' | '//' | '%') unary)* */
  parseTerm() {
    let left = this.parseUnary();
    while (this.atOp('*') || this.atOp('/') || this.atOp('//') || this.atOp('%')) {
      const op = this.next().value;
      const right = this.parseUnary();
      if (op === '*') left = pyMul(left, right);
      else if (op === '/') left = pyTrueDiv(left, right);
      else if (op === '//') left = pyFloorDiv(left, right);
      else left = pyMod(left, right);
    }
    return left;
  }

  /** unary := ('+' | '-') unary | power */
  parseUnary() {
    if (this.atOp('-')) {
      this.next();
      return pyNegate(this.parseUnary());
    }
    if (this.atOp('+')) {
      this.next();
      return this.parseUnary();
    }
    return this.parsePower();
  }

  /** power := atom ['**' unary]  (right associative) */
  parsePower() {
    const base = this.parseAtom();
    if (this.atOp('**')) {
      this.next();
      return pyPow(base, this.parseUnary());
    }
    return base;
  }

  parseAtom() {
    const token = this.peek();

    if (token.type === 'number') {
      this.next();
      return token.value;
    }

    if (token.type === 'string') {
      let text = '';
      let isBytes = false;
      while (this.peek().type === 'string') {
        const part = this.next();
        if (part.prefix.includes('b')) isBytes = true;
        text += part.value;
      }
      if (isBytes) {
        return new PyBytes(Array.from(text, (char) => char.charCodeAt(0) & 0xff));
      }
      return text;
    }

    if (token.type === 'name') {
      this.next();
      if (token.value === 'True') return true;
      if (token.value === 'False') return false;
      if (token.value === 'None') return null;
      if (this.atOp('(')) {
        const callable = BUILTINS[token.value];
        if (!callable) throw new PyError('NameError', `name '${token.value}' is not defined`);
        return callable(this.parseCallArguments());
      }
      throw new PyError('NameError', `name '${token.value}' is not defined`);
    }

    if (token.type === 'op') {
      if (token.value === '[') return this.parseList();
      if (token.value === '(') return this.parseParenthesized();
      if (token.value === '{') return this.parseBraced();
    }

    throw SYNTAX_ERROR();
  }

  parseCallArguments() {
    this.eatOp('(');
    const args = [];
    while (!this.atOp(')')) {
      args.push(this.parseExpression());
      if (this.atOp(',')) this.next();
      else break;
    }
    this.eatOp(')');
    return args;
  }

  parseList() {
    this.eatOp('[');
    const items = [];
    while (!this.atOp(']')) {
      items.push(this.parseExpression());
      if (this.atOp(',')) this.next();
      else break;
    }
    this.eatOp(']');
    return items;
  }

  parseParenthesized() {
    this.eatOp('(');
    if (this.atOp(')')) {
      this.next();
      return new PyTuple([]);
    }
    const items = [this.parseExpression()];
    let isTuple = false;
    while (this.atOp(',')) {
      this.next();
      isTuple = true;
      if (this.atOp(')')) break;
      items.push(this.parseExpression());
    }
    this.eatOp(')');
    return isTuple ? new PyTuple(items) : items[0];
  }

  /** `{}` is a dict; `{a: b}` a dict; `{a, b}` a set. */
  parseBraced() {
    this.eatOp('{');
    if (this.atOp('}')) {
      this.next();
      return new PyDict();
    }
    const first = this.parseExpression();
    if (this.atOp(':')) {
      this.next();
      const dict = new PyDict();
      dict.set(first, this.parseExpression());
      while (this.atOp(',')) {
        this.next();
        if (this.atOp('}')) break;
        const key = this.parseExpression();
        this.eatOp(':');
        dict.set(key, this.parseExpression());
      }
      this.eatOp('}');
      return dict;
    }
    const set = new PySet([first]);
    while (this.atOp(',')) {
      this.next();
      if (this.atOp('}')) break;
      set.add(this.parseExpression());
    }
    this.eatOp('}');
    return set;
  }
}

/** Python's `eval()` for the supported expression subset. */
export function pyEval(source) {
  if (codePointLength(source.trim()) === 0) throw SYNTAX_ERROR();
  const parser = new Parser(tokenize(source));
