    }

    if (token.type === 'name') {
      this.next();
      if (token.value === 'True') return true;
      if (token.value === 'False') return false;
      if (token.value === 'None') return null;
      if (this.atOp('(')) {
        const callable = BUILTINS[token.value];
        if (!callable) throw new PyError('NameError', `name '${token.value}' is not defined`);
