/**
 * boltons/iterutils.mjs — behavioural re-implementation of the iterutils
 * helpers used by the program: flatten, chunked, bucketize, partition.
 */

import {
  PyBytes,
  PyDict,
  PyError,
  PyRange,
  PySet,
  PyTuple,
  typeName,
} from '../pyvalues.mjs';

/**
 * `is_iterable()` — strings and bytes are iterable in Python too, but
 * flatten() deliberately treats them as scalars, which is handled below.
 */
export function isIterable(value) {
  if (typeof value === 'string' || value instanceof PyBytes) return true;
  return (
    Array.isArray(value) ||
    value instanceof PyTuple ||
    value instanceof PySet ||
    value instanceof PyDict ||
    value instanceof PyRange ||
    (value !== null && typeof value === 'object' && typeof value.pyIter === 'function')
  );
}

/** `is_scalar()` — not iterable, or a string/bytes. */
export function isScalar(value) {
  return !isIterable(value) || typeof value === 'string' || value instanceof PyBytes;
}

/** Materialise any supported iterable into a JS array of elements. */
export function toArray(value) {
  if (Array.isArray(value)) return value.slice();
  if (typeof value === 'string') return Array.from(value);
  if (value instanceof PyTuple) return value.items.slice();
  if (value instanceof PySet) return value.values();
  if (value instanceof PyDict) return value.keys(); // iterating a dict yields keys
  if (value instanceof PyRange) return value.toArray();
  if (value instanceof PyBytes) return Array.from(value.bytes, (byte) => BigInt(byte));
  if (value !== null && typeof value === 'object' && typeof value.pyIter === 'function') {
    return value.pyIter();
  }
  throw new PyError('TypeError', `'${typeName(value)}' object is not iterable`);
}

/**
 * `flatten(iterable)` — recursively yields non-iterable items. Strings and
 * bytes count as scalars, so they are never split into characters, while
 * dicts contribute their keys.
 */
export function flatten(iterable) {
  const out = [];
  const walk = (items) => {
    for (const item of items) {
      if (isIterable(item) && typeof item !== 'string' && !(item instanceof PyBytes)) {
        walk(toArray(item));
      } else {
        out.push(item);
      }
    }
  };
  walk(toArray(iterable));
  return out;
}

/**
 * `chunked(src, size)` — consecutive slices of length `size`; without a
 * `fill` value the trailing partial chunk is returned as-is.
 */
export function chunked(src, size) {
  const items = toArray(src);
  const chunkSize = Number(size);
  if (chunkSize <= 0) throw new PyError('ValueError', 'expected a positive integer size');
  const out = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    out.push(items.slice(i, i + chunkSize));
  }
  return out;
}

/**
 * `bucketize(src, key_func)` — dict mapping each key to the list of items
 * that produced it, keys ordered by first appearance.
 */
export function bucketize(src, keyFunc) {
  const buckets = new PyDict();
  for (const item of toArray(src)) {
    const key = keyFunc(item);
    const bucket = buckets.get(key);
    if (bucket === undefined) buckets.set(key, [item]);
    else bucket.push(item);
  }
  return buckets;
}

/**
 * `partition(src, key)` — bucketizes on the key function and returns the
 * `True` and `False` buckets as a 2-tuple. Keys that are neither True nor
 * False are dropped, exactly as in the original implementation.
 */
export function partition(src, keyFunc) {
  const buckets = bucketize(src, keyFunc);
  return new PyTuple([buckets.get(true, []), buckets.get(false, [])]);
}

