import { basename } from 'node:path';

export class ArgumentParser {
  constructor({ prog = defaultProg(), description = null } = {}) {
    this.prog = prog;
    this.description = description;
    /** @type {Array<{name: string, dest: string, metavar: string, required: boolean, help: string|null}>} */
    this.arguments = [];
  }

  /**
   * `add_argument('--a', type=str, required=True, help='...')`.
   * `type` is accepted for signature parity; every value arrives as a string.
   */
  addArgument(flag, { type = String, required = false, help = null, metavar = null } = {}) {
    if (!flag.startsWith('--')) {
      throw new Error(`only long options are supported, got: ${flag}`);
    }
    const dest = flag.slice(2).replace(/-/g, '_');
    this.arguments.push({
      name: flag,
      dest,
      type,
      required,
      help,
      metavar: metavar || dest.toUpperCase(),
    });
    return this;
  }

  formatUsage() {
    const parts = this.arguments.map((arg) =>
      arg.required ? `${arg.name} ${arg.metavar}` : `[${arg.name} ${arg.metavar}]`,
    );
    return `usage: ${this.prog} [-h] ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = [['-h, --help', 'show this help message and exit']];
    for (const arg of this.arguments) {
      invocations.push([`${arg.name} ${arg.metavar}`, arg.help || '']);
    }
    const width = Math.max(...invocations.map(([text]) => text.length)) + 2;

    let out = this.formatUsage();
    if (this.description) out += `\n${this.description}\n`;
    out += '\noptions:\n';
    for (const [text, help] of invocations) {
      out += help ? `  ${text.padEnd(width, ' ')}${help}\n` : `  ${text}\n`;
    }
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Returns an object keyed by each argument's dest, like argparse.Namespace. */
  parseArgs(argv = process.argv.slice(2)) {
    const known = new Map(this.arguments.map((arg) => [arg.name, arg]));
    const values = {};
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      const equals = token.indexOf('=');
      const flag = token.startsWith('--') && equals !== -1 ? token.slice(0, equals) : token;
      const arg = known.get(flag);

      if (arg === undefined) {
        extras.push(token);
