#!/bin/bash
# Differential test: /workspace/dataset/test19_executable vs node /output/test19.mjs
PY=/workspace/dataset/test19_executable
JS="node /output/test19.mjs"
pass=0; fail=0
run_case() {
  local desc="$1"; shift
  local pyout jsout
  pyout=$("$PY" "$@" 2>/dev/null); pyrc=$?
  jsout=$($JS "$@" 2>/dev/null); jsrc=$?
  if [ "$pyout" == "$jsout" ] && [ "$pyrc" == "$jsrc" ]; then
    pass=$((pass+1))
  else
    fail=$((fail+1))
    echo "FAIL: $desc  (args: $*)  rc py=$pyrc js=$jsrc"
    diff <(printf '%s\n' "$pyout") <(printf '%s\n' "$jsout") | head -12
  fi
}

while IFS= read -r line; do
  [ -z "$line" ] && continue
  run_case "$line" --a "$line"
done <<'EOF'
{'a': 1, 'b': 2, 'c': 3}
{}
{'a': [1,2], 'b': {'c': 3, 'd': 4}, 'e': 5}
