/**
 * fuzz.mjs — generates random Python dict literals, then compares the output
 * of the reference executable with the Node.js port.
 */
import { execFileSync } from 'node:child_process';

const PY = '/workspace/dataset/test19_executable';
const JS = '/output/test19.mjs';

let seed = Number(process.argv[3] || 12345);
const rand = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
const pick = (arr) => arr[Math.floor(rand() * arr.length)];
const int = (n) => Math.floor(rand() * n);

const WORDS = ['a', 'b', 'key', 'name', 'x1', 'z_z', 'foo bar', '中文', "it's", 'say "hi"', '', 'tab\\there'];

function scalar() {
  switch (int(9)) {
    case 0: return String(int(200) - 100);
    case 1: return `${int(1000) / 8}`;
    case 2: return `'${pick(WORDS)}'`;
    case 3: return pick(['True', 'False', 'None']);
    case 4: return pick(['0', '-0.0', '1e16', '1e-5', '1e21', '0.1', '1.0', '123456789012345678901234567890']);
    case 5: return String(int(1e6) * 1000000);
    case 6: return pick(["float('inf')", "float('nan')", "float('-inf')"]);
    case 7: return `${-int(50)}.${int(100)}`;
    default: return String(int(10));
  }
}

function container(depth) {
  const n = 1 + int(4);
  const parts = [];
  switch (int(4)) {
    case 0:
      for (let i = 0; i < n; i++) parts.push(value(depth + 1));
      return `[${parts.join(', ')}]`;
    case 1:
      for (let i = 0; i < n; i++) parts.push(value(depth + 1));
      return `(${parts.join(', ')}${n === 1 ? ',' : ''})`;
    case 2:
      for (let i = 0; i < n; i++) parts.push(`${key()}: ${value(depth + 1)}`);
      return `{${parts.join(', ')}}`;
    default:
      return pick(['[]', '{}', '()', '[[]]', '[{}]', '({},)']);
  }
}

function value(depth = 0) {
  if (depth >= 3 || rand() < 0.55) return scalar();
  return container(depth);
}

function key() {
  return rand() < 0.75 ? `'${pick(WORDS)}${int(5)}'` : pick([String(int(20)), 'True', 'None', '(1, 2)', '1.5']);
}

function dictLiteral() {
  const n = int(7);
  const parts = [];
  for (let i = 0; i < n; i++) parts.push(`${key()}: ${value()}`);
  return `{${parts.join(', ')}}`;
}

function capture(cmd, cmdArgs) {
  try {
    return { out: execFileSync(cmd, cmdArgs, { encoding: 'utf8' }), rc: 0 };
  } catch (error) {
    return { out: String(error.stdout ?? ''), rc: error.status ?? -1 };
  }
}

const total = Number(process.argv[2] || 200);
let fail = 0;
for (let i = 0; i < total; i++) {
  const literal = dictLiteral();
  const expected = capture(PY, ['--a', literal]);
  const actual = capture('node', [JS, '--a', literal]);
  if (expected.out !== actual.out || expected.rc !== actual.rc) {
    fail++;
    console.log(`\nFAIL #${i} rc py=${expected.rc} js=${actual.rc}\ninput: ${literal}`);
    const a = expected.out.split('\n');
    const b = actual.out.split('\n');
    for (let l = 0; l < Math.max(a.length, b.length); l++) {
      if (a[l] !== b[l]) console.log(`  line ${l + 1}:\n    py: ${a[l]}\n    js: ${b[l]}`);
